import("stdfaust.lib");

// Parameters
stringLength = hslider("String Length [unit:ms]", 20, 5, 100, 1) : si.smoo;
pluckPos = hslider("Pluck Position", 0.5, 0, 1, 0.01);
gain = hslider("Gain", 0.5, 0, 1, 0.01);

// Constants
MAXD = 48000; // Maximum delay for Karplus-Strong algorithm

// Delay line and feedback
delayLine(x) = de.fdelay(MAXD, stringLength * ma.SR / 1000.0, x);
feedback = delayLine : *(pluckPos);

// Karplus-Strong synthesis
karplusStrong(x) = (x + feedback) * gain;

// Process
process = karplusStrong, karplusStrong;
